-- ============================================================
-- 003_seed_demo.sql
-- Dados de demonstracao. NAO aplicar em producao: o runner
-- `bin/migrate.php` ignora arquivos com sufixo `_demo` quando
-- APP_ENV=production.
--
-- Conteudo:
--   * 10 clientes (CPFs com digito verificador valido, 8 ACTIVE,
--     1 INACTIVE e 1 BLOCKED para exercitar os erros 403 do /auth/cpf)
--   * 15 veiculos
--   * 10 servicos de catalogo e 15 pecas em estoque
--   * 120 ordens de servico distribuidas nos ultimos 30 dias,
--     cobrindo os 7 status da maquina de estados
--   * service_order_status_history coerente: timestamps crescentes e
--     duracoes plausiveis por etapa (diagnostico ~2h, aguardando
--     aprovacao ~8h, execucao ~6h)
--
-- Todas as datas sao RELATIVAS a NOW(3), entao o dashboard fica
-- populado em qualquer dia que o seed for aplicado.
-- Idempotente: ids fixos + INSERT IGNORE.
-- ============================================================

-- Instante de referencia unico. Sem isso, cada NOW(3) das ~1100 linhas
-- abaixo seria avaliado em um momento ligeiramente diferente e o
-- created_at da OS nao bateria com o primeiro registro do historico.
SET @seed_now = NOW(3);

